const { execSync } = require('child_process');

const SCRIPT = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\automacao-n8n\\gerar-handoff-sessao.js';
const AUDITORIA_DIR = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria';

let saida = null;
let erro = null;
try {
  saida = execSync(`node "${SCRIPT}" "${AUDITORIA_DIR}"`, { encoding: 'utf8', timeout: 60000, maxBuffer: 10 * 1024 * 1024 });
} catch (e) {
  erro = e.message || String(e);
}

return [{ json: { erro, saida: saida ? saida.trim() : null } }];
